package api

import (
	"bytes"
	"encoding/json"
	"fmt"
	"net/http"
	"net/http/httptest"
	"path/filepath"
	"sync"
	"testing"

	"github.com/xjeey8iust/sen-sbom-inventory/internal/model"
	"github.com/xjeey8iust/sen-sbom-inventory/internal/store"
)

func newTestRouter(t *testing.T) (*ginEngineShim, *store.Store) {
	t.Helper()
	st, err := store.Open(filepath.Join(t.TempDir(), "service.db"))
	if err != nil {
		t.Fatalf("open: %v", err)
	}
	t.Cleanup(func() { st.Close() })
	return &ginEngineShim{router: NewRouter(st)}, st
}

type ginEngineShim struct{ router interface{ ServeHTTP(http.ResponseWriter, *http.Request) } }

func (g *ginEngineShim) post(t *testing.T, body string) *httptest.ResponseRecorder {
	t.Helper()
	return g.request(t, http.MethodPost, "/sboms", body)
}

func (g *ginEngineShim) get(t *testing.T, target string) *httptest.ResponseRecorder {
	t.Helper()
	return g.request(t, http.MethodGet, target, "")
}

func (g *ginEngineShim) request(t *testing.T, method, target, body string) *httptest.ResponseRecorder {
	t.Helper()
	var reader *bytes.Reader
	if body != "" || method == http.MethodPost {
		reader = bytes.NewReader([]byte(body))
	} else {
		reader = bytes.NewReader(nil)
	}
	req := httptest.NewRequest(method, target, reader)
	if method == http.MethodPost {
		req.Header.Set("Content-Type", "application/json")
	}
	rec := httptest.NewRecorder()
	g.router.ServeHTTP(rec, req)
	return rec
}

func decodeBody(t *testing.T, rec *httptest.ResponseRecorder, v any) {
	t.Helper()
	if err := json.Unmarshal(rec.Body.Bytes(), v); err != nil {
		t.Fatalf("decode %q: %v", rec.Body.String(), err)
	}
}

func expectError(t *testing.T, rec *httptest.ResponseRecorder, status int, code string) {
	t.Helper()
	if rec.Code != status {
		t.Fatalf("status = %d, want %d; body %s", rec.Code, status, rec.Body.String())
	}
	var envelope struct {
		Error struct {
			Code    string `json:"code"`
			Message string `json:"message"`
		} `json:"error"`
	}
	decodeBody(t, rec, &envelope)
	if envelope.Error.Code != code {
		t.Fatalf("code = %q, want %q", envelope.Error.Code)
	}
	if envelope.Error.Message == "" {
		t.Fatalf("error message is empty")
	}
	for _, leaked := range []string{"SQLITE", "sql:", "goroutine", "/", ".go:"} {
		if bytes.Contains(rec.Body.Bytes(), []byte(leaked)) {
			t.Fatalf("error response leaks %q: %s", leaked, rec.Body.String())
		}
	}
}

func TestRegisterCreatesNormalizedManifest(t *testing.T) {
	eng, _ := newTestRouter(t)

	// Whitespace everywhere, components and dependencies in non-sorted order.
	body := `{
		"artifact": "  atlas  ",
		"version": " 1.2.0 ",
		"components": [
			{"coordinate": " lib-z ", "license": " MIT ", "dependencies": [" lib-a "]},
			{"coordinate": "lib-a", "license": "Apache-2.0", "dependencies": []}
		]
	}`
	rec := eng.post(t, body)
	if rec.Code != http.StatusCreated {
		t.Fatalf("status = %d, body %s", rec.Code, rec.Body.String())
	}
	var got model.SBOM
	decodeBody(t, rec, &got)
	if got.ID <= 0 {
		t.Fatalf("id = %d, want positive integer", got.ID)
	}
	want := model.SBOM{
		ID:       got.ID,
		Artifact: "atlas",
		Version:  "1.2.0",
		Components: []model.Component{
			{Coordinate: "lib-a", License: "Apache-2.0", Dependencies: []string{}},
			{Coordinate: "lib-z", License: "MIT", Dependencies: []string{"lib-a"}},
		},
	}
	assertSBOMEqual(t, &got, &want)
}

func TestRegisterAllowsEmptyComponentsAndDependencies(t *testing.T) {
	eng, _ := newTestRouter(t)
